def merge_intervals(intervals):
    # Validate each interval
    for start, end in intervals:
        if start > end:
            raise ValueError("start > end")
    # Sort by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = []
    for s, e in sorted_intervals:
        if not merged:
            merged.append([s, e])
        else:
            last_s, last_e = merged[-1]
            if s <= last_e:  # overlap or touch
                merged[-1][1] = max(last_e, e)
            else:
                merged.append([s, e])
    return merged

def run_tests():
    test_cases = [
        {
            "input": [[1, 3], [2, 6], [8, 10], [15, 18]],
            "expected": [[1, 6], [8, 10], [15, 18]],
            "should_raise": False,
        },
        {
            "input": [[1, 4], [4, 5]],
            "expected": [[1, 5]],
            "should_raise": False,
        },
        {
            "input": [],
            "expected": [],
            "should_raise": False,
        },
        {
            "input": [[3, 1]],
            "expected": None,
            "should_raise": True,
        },
        {
            "input": [[1,5],[2,3]],
            "expected": [[1,5]],
            "should_raise": False,
        },
        {
            "input": [[1,2],[2,3]],
            "expected": [[1,3]],
            "should_raise": False,
        },
        {
            "input": [[1,2],[3,4]],
            "expected": [[1,2],[3,4]],
            "should_raise": False,
        },
        {
            "input": [[1,4],[2,5],[6,8],[7,10]],
            "expected": [[1,5],[6,10]],
            "should_raise": False,
        },
        {
            "input": [[5,5],[5,5]],
            "expected": [[5,5]],
            "should_raise": False,
        },
        {
            "input": [[1,2],[3,4]],
            "expected": [[1,2],[3,4]],
            "should_raise": False,
        },
    ]

    for i, tc in enumerate(test_cases):
        intervals = tc["input"]
        expected = tc["expected"]
        should_raise = tc["should_raise"]
        # Keep original to ensure not modified
        original = [list(x) for x in intervals]  # deep copy
        try:
            result = merge_intervals(intervals)
        except ValueError:
            if should_raise:
                pass
            else:
                raise AssertionError(f"Test {i} unexpectedly raised ValueError")
        else:
            if should_raise:
                raise AssertionError(f"Test {i} should have raised ValueError but didn't")
            if result != expected:
                raise AssertionError(f"Test {i} failed: got {result}, expected {expected}")
        # Ensure input not modified
        if intervals != original:
            raise AssertionError(f"Test {i} modified input list")
    print("ALL TESTS PASSED")

if __name__ == "__main__":
    run_tests()

